function Vfx(pos, name)
	local e = ChaosVfx[name]
	if not e or not pos then
		return false
	end
	Position(pos.x + e.dx, pos.y + e.dy, pos.z):sendMagicEffect(e.id)
	return true
end

-- directional effects (name_n, name_ne, ... name_nw) by a creature direction (NORTH .. NORTHWEST)
local DIRNAME = {[0] = "n", [1] = "e", [2] = "s", [3] = "w", [4] = "sw", [5] = "se", [6] = "nw", [7] = "ne"}
function VfxDir(pos, base, direction)
	return Vfx(pos, base .. "_" .. (DIRNAME[direction] or "s"))
end

function VfxShoot(fromPos, toPos, name)
	local m = ChaosVfxMissile[name]
	if not m or not fromPos or not toPos then
		return false
	end
	Position(fromPos.x + m.dx, fromPos.y + m.dy, fromPos.z):sendDistanceEffect(
		Position(toPos.x + m.dx, toPos.y + m.dy, toPos.z), m.id)
	return true
end
